    48	/**
    49	 * Map to store translated values for each locale.
    50	 * This is used to avoid translating the same phrase multiple times.
    51	 *
    52	 * The data is stored in the following format:
    53	 *
    54	 * {
    55	 *  "en": {
    56	 *   "name": "Name",
    57	 * }
    58	 *
    59	 * Note: We are not storing any translated values for phrases with variables,
    60	 * as they have higher chance of being unique, so we'll end up wasting space
    61	 * in our cache.
    62	 */
    63	const translationCache = new Map<ValueOf<typeof CONST.LOCALES>, Map<TranslationPaths, string>>(
    64	    Object.values(CONST.LOCALES).reduce((cache, locale) => {
    65	        cache.push([locale, new Map<TranslationPaths, string>()]);
