    70	/**
    71	 * Helper function to get the translated string for given
    72	 * locale and phrase. This function is used to avoid
    73	 * duplicate code in getTranslatedPhrase and translate functions.
    74	 *
    75	 * This function first checks if the phrase is already translated
    76	 * and in the cache, it returns the translated value from the cache.
    77	 *
    78	 * If the phrase is not translated, it checks if the phrase is
    79	 * available in the given locale. If it is, it translates the
    80	 * phrase and stores the translated value in the cache and returns
    81	 * the translated value.
    82	 */
    83	function getTranslatedPhrase<TKey extends TranslationPaths>(
    84	    language: 'en' | 'es' | 'es-ES',
    85	    phraseKey: TKey,
    86	    fallbackLanguage: 'en' | 'es' | null,
    87	    ...parameters: TranslationParameters<TKey>
    88	): string | null {
    89	    // Get the cache for the above locale
    90	    const cacheForLocale = translationCache.get(language);
    91	
    92	    // Directly access and assign the translated value from the cache, instead of
    93	    // going through map.has() and map.get() to avoid multiple lookups.
    94	    const valueFromCache = cacheForLocale?.get(phraseKey);
    95	
    96	    // If the phrase is already translated, return the translated value
    97	    if (valueFromCache) {
    98	        return valueFromCache;
    99	    }
