   101	    const translatedPhrase = translations?.[language]?.[phraseKey];
   102	
   103	    if (translatedPhrase) {
   104	        if (typeof translatedPhrase === 'function') {
   105	            /**
   106	             * If the result of `translatedPhrase` is an object, check if it contains the 'count' parameter
   107	             * to handle pluralization logic.
   108	             * Alternatively, before evaluating the translated result, we can check if the 'count' parameter
   109	             * exists in the passed parameters.
   110	             */
   111	            const translateFunction = translatedPhrase as unknown as (...parameters: TranslationParameters<TKey>) => string | PluralForm;
   112	            const translateResult = translateFunction(...parameters);
   113	
   114	            if (typeof translateResult === 'string') {
   115	                return translateResult;
   116	            }
   117	
   118	            const phraseObject = parameters[0] as {count?: number};
   119	            if (typeof phraseObject?.count !== 'number') {
   120	                throw new Error(`Invalid plural form for '${phraseKey}'`);
   121	            }
   122	
   123	            const pluralRule = new Intl.PluralRules(language).select(phraseObject.count);
   124	
   125	            const pluralResult = translateResult[pluralRule];
   126	            if (pluralResult) {
   127	                if (typeof pluralResult === 'string') {
   128	                    return pluralResult;
   129	                }
   130	
   131	                return pluralResult(phraseObject.count);
   132	            }
   133	
   134	            if (typeof translateResult.other === 'string') {
   135	                return translateResult.other;
   136	            }
   137	
   138	            return translateResult.other(phraseObject.count);
   139	        }
   140	
   141	        // We set the translated value in the cache only for the phrases without parameters.
   142	        cacheForLocale?.set(phraseKey, translatedPhrase);
   143	        return translatedPhrase;
   144	    }
