   153	    if (fallbackTranslatedPhrase) {
   154	        return fallbackTranslatedPhrase;
   155	    }
   156	
   157	    if (fallbackLanguage !== CONST.LOCALES.DEFAULT) {
   158	        Log.alert(`${phraseKey} was not found in the ${fallbackLanguage} locale`);
   159	    }
