   170	 */
   171	function translate<TPath extends TranslationPaths>(desiredLanguage: 'en' | 'es' | 'es-ES' | 'es_ES', path: TPath, ...parameters: TranslationParameters<TPath>): string {
   172	    // Search phrase in full locale e.g. es-ES
   173	    const language = desiredLanguage === CONST.LOCALES.ES_ES_ONFIDO ? CONST.LOCALES.ES_ES : desiredLanguage;
   174	    // Phrase is not found in full locale, search it in fallback language e.g. es
   175	    const languageAbbreviation = desiredLanguage.substring(0, 2) as 'en' | 'es';
   176	
   177	    const translatedPhrase = getTranslatedPhrase(language, path, languageAbbreviation, ...parameters);
   178	    if (translatedPhrase !== null && translatedPhrase !== undefined) {
   179	        return translatedPhrase;
   180	    }
   181	
   182	    // Phrase is not found in default language, on production and staging log an alert to server
   183	    // on development throw an error
   184	    if (Config.IS_IN_PRODUCTION || Config.IS_IN_STAGING) {
   185	        const phraseString = Array.isArray(path) ? path.join('.') : path;
