   210	/**
   211	 * Format an array into a string with comma and "and" ("a dog, a cat and a chicken")
   212	 */
   213	function formatList(components: string[]) {
   214	    const listFormat = getPreferredListFormat();
   215	    return listFormat.format(components);
   216	}
   217	
   218	function formatMessageElementList<E extends MessageElementBase>(elements: readonly E[]): ReadonlyArray<E | MessageTextElement> {
   219	    const listFormat = getPreferredListFormat();
   220	    const parts = listFormat.formatToParts(elements.map((e) => e.content));
   221	    const resultElements: Array<E | MessageTextElement> = [];
   222	
   223	    let nextElementIndex = 0;
   224	    for (const part of parts) {
   225	        if (part.type === 'element') {
   226	            /**
   227	             * The standard guarantees that all input elements will be present in the constructed parts, each exactly
   228	             * once, and without any modifications: https://tc39.es/ecma402/#sec-createpartsfromlist
   229	             */
   230	            const element = elements[nextElementIndex++];
   231	
   232	            resultElements.push(element);
   233	        } else {
   234	            const literalElement: MessageTextElement = {
   235	                kind: 'text',
   236	                content: part.value,
   237	            };
   238	
   239	            resultElements.push(literalElement);
   240	        }
   241	    }
   242	
   243	    return resultElements;
   244	}
