   246	/**
   247	 * Returns the user device's preferred language.
   248	 */
   249	function getDevicePreferredLocale(): Locale {
   250	    return RNLocalize.findBestAvailableLanguage([CONST.LOCALES.EN, CONST.LOCALES.ES])?.languageTag ?? CONST.LOCALES.DEFAULT;
   251	}
